import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../crm_providers.dart';
import '../data/crm_inbox_repository.dart';

class WhatsAppAgentScreen extends ConsumerStatefulWidget { const WhatsAppAgentScreen({super.key}); @override ConsumerState<WhatsAppAgentScreen> createState() => _WhatsAppAgentScreenState(); }
class _WhatsAppAgentScreenState extends ConsumerState<WhatsAppAgentScreen> {
  late Future<WhatsAppAgentState> agent;
  bool busy = false;
  @override void initState() { super.initState(); agent = ref.read(crmInboxRepositoryProvider).agent(); }
  void reload() { setState(() => agent = ref.read(crmInboxRepositoryProvider).agent()); ref.invalidate(whatsappIntegrationProvider); }
  @override Widget build(BuildContext context) { final integration = ref.watch(whatsappIntegrationProvider); return Scaffold(appBar: AppBar(title: const Text('WhatsApp Agent'), actions: [IconButton(tooltip: 'Refresh', onPressed: reload, icon: const Icon(Icons.refresh))]), body: ListView(padding: const EdgeInsets.all(20), children: [Text('Grounded in Business Brain with human takeover support.', style: Theme.of(context).textTheme.bodyLarge), const SizedBox(height: 18), FutureBuilder<WhatsAppAgentState>(future: agent, builder: (context, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const LinearProgressIndicator(); if (snapshot.hasError) return Column(children: [Text('Agent status unavailable: ${snapshot.error}'), TextButton(onPressed: reload, child: const Text('Try again'))]); final state = snapshot.data!; return Card(child: ListTile(title: Text(state.active ? 'Active' : 'Paused'), subtitle: Text(state.active ? 'Automatic replies are enabled for eligible WhatsApp conversations.' : 'The agent will not automatically process new eligible messages.'), trailing: FilledButton(onPressed: busy ? null : () => _setStatus(state.active ? 'paused' : 'active'), child: Text(busy ? 'Saving…' : state.active ? 'Pause Agent' : 'Activate Agent')))); }), const SizedBox(height: 12), integration.when(loading: () => const LinearProgressIndicator(), error: (e, _) => Card(child: ListTile(leading: const Icon(Icons.warning_amber), title: const Text('Integration unavailable'), subtitle: Text('$e'))), data: (value) { final connected = value?['status'] == 'connected'; return Card(child: ListTile(leading: Icon(connected ? Icons.check_circle : Icons.warning, color: connected ? Colors.green : Colors.orange), title: Text(connected ? 'Connected' : 'WhatsApp not configured'), subtitle: Text(connected ? 'WhatsApp integration is available.' : 'Meta WhatsApp configuration is required before live conversations can be sent or received.'))); }), const SizedBox(height: 12), const Text('Prepare the information your agent uses:'), const SizedBox(height: 8), Wrap(spacing: 8, runSpacing: 8, children: [for (final item in {'Company Profile': '/business-brain/company-profile', 'Business Hours': '/business-brain/hours', 'Services': '/business-brain/services', 'FAQs': '/business-brain/knowledge', 'Policies': '/business-brain/policies', 'Customer Engagement': '/business-brain/engagement', 'Documents': '/business-brain/documents'}.entries) ActionChip(label: Text(item.key), onPressed: () => context.go(item.value))]) ])); }
  Future<void> _setStatus(String status) async { setState(() => busy = true); try { await ref.read(crmInboxRepositoryProvider).setAgentStatus(status); reload(); } catch (e) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Agent status could not be changed: $e'))); } finally { if (mounted) setState(() => busy = false); } }
}
